'pooja' => ['mangal' => ['name' => 'મંગળ દોષ શાંતિ / હનુમાન પૂજા', 'purpose' => 'લગ્ન, સ્વભાવ અને મિલકત પર મંગળની કઠોર અસર શાંત કરવી.', 'why' => 'તમારી કુંડળીમાં મંગળ દોષ છે અને મંગળ તેને જાતે રદ કરે એટલો મજબૂત નથી.', 'timing' => 'મંગળવાર; ઘણા પરિવારો લગ્ન પહેલાં એકવાર કરે છે.', 'involves' => 'લાલ ફૂલ, સિંદૂર અને મસૂરની દાળથી હનુમાન કે મંગળ પૂજા; ઇચ્છો તો પૂજારી પાસે મંગળ મંત્ર જાપ.', 'cost' => 'ઘરે: ₹0–500 · મંદિર પૂજા: ₹1,100–5,100'], 'kaal_sarp' => ['name' => 'કાળ સર્પ દોષ પૂજા', 'purpose' => 'રાહુ–કેતુ સાથે જોડાયેલા અવરોધો અને અચાનક આંચકા ઘટાડવા.', 'why' => 'તમારી કુંડળીમાં બધા ગ્રહો રાહુ અને કેતુની વચ્ચે છે (કાળ સર્પ).', 'timing' => 'એકવાર, નાગ પંચમી, અમાસ કે સોમવારે.', 'involves' => 'નાગ પૂજા સાથે રાહુ–કેતુ શાંતિ, સામાન્ય રીતે ત્ર્યંબકેશ્વર, ઉજ્જૈન કે શિવ મંદિરમાં.', 'cost' => 'મંદિર: ₹2,100–11,000'], 'shani' => ['name' => 'શનિ શાંતિ / હનુમાન પૂજા', 'purpose' => 'સાડાસાતી કે ઢૈયામાં શનિનું દબાણ ઘટાડવું.', 'why' => 'શનિ અત્યારે તમારા ચંદ્રથી સંવેદનશીલ ભાવમાં ગોચર કરે છે.', 'timing' => 'આ સમય ચાલે ત્યાં સુધી દર શનિવારે.', 'involves' => 'શનિ પર સરસવના તેલનો અભિષેક, હનુમાન ચાલીસા, કાળી વસ્તુઓનું દાન; ઇચ્છો તો શનિ મંત્ર જાપ.', 'cost' => 'ઘરે: ₹0–300 · મંદિર પૂજા: ₹500–5,100'], 'pitru' => ['name' => 'પિતૃ તર્પણ / શ્રાદ્ધ', 'purpose' => 'પૂર્વજોનું સન્માન અને પિતૃ દોષ દૂર કરવો.', 'why' => 'તમારી કુંડળીમાં પિતૃ દોષ છે (પીડિત સૂર્ય / 9મો ભાવ).', 'timing' => 'દર અમાસે; દર વર્ષે પિતૃ પક્ષ. નારાયણ બલિ ફક્ત પૂજારીની સંપૂર્ણ તપાસ પછી.', 'involves' => 'જળ, કાળા તલ અને કુશાથી તર્પણ; બ્રાહ્મણ કે જરૂરિયાતમંદને ભોજન.', 'cost' => 'ઘરે: ₹0–500 · પૂજારી સાથે: ₹1,100–15,000'], 'grahan' => ['name' => 'ગ્રહણ દોષ શાંતિ', 'purpose' => 'સૂર્ય કે ચંદ્ર સાથે રાહુ/કેતુની અસર ઘટાડવી.', 'why' => 'તમારી કુંડળીમાં રાહુ કે કેતુ સૂર્ય/ચંદ્ર સાથે છે (ગ્રહણ દોષ).', 'timing' => 'એકવાર, ગ્રહણના દિવસે કે અમાસે.', 'involves' => 'રાહુ–કેતુ મંત્ર જાપ, દુર્ગા કે શિવ પૂજા, પૂજા પછી દાન.', 'cost' => 'મંદિર: ₹1,100–7,100'], 'guru' => ['name' => 'ગુરુ (બૃહસ્પતિ) પૂજા', 'purpose' => 'જ્ઞાન, ગુરુજનો અને ભાગ્યને સહારો આપવો.', 'why' => 'તમારી કુંડળીમાં ગુરુ રાહુથી પીડિત (ગુરુ ચાંડાલ) અને નબળો છે.', 'timing' => 'ગુરુવાર; ગુરુ પૂર્ણિમા.', 'involves' => 'પીળાં ફૂલ, ચણાની દાળ અને હળદરથી વિષ્ણુ કે બૃહસ્પતિ પૂજા; ગુરુજનોનું સન્માન.', 'cost' => 'ઘરે: ₹0–300 · મંદિર: ₹500–3,100'], 'rudra' => ['name' => 'રુદ્રાભિષેક', 'purpose' => 'મનની શાંતિ અને ભાવનાત્મક સ્થિરતા માટે.', 'why' => 'તમારા ચંદ્રને સહારાની જરૂર છે (નબળો ચંદ્ર કે કેમદ્રુમ).', 'timing' => 'સોમવાર; શ્રાવણ માસ.', 'involves' => 'રુદ્રમ પાઠ સાથે શિવલિંગ પર જળ, દૂધ અને મધથી અભિષેક.', 'cost' => 'ઘરે: ₹0–500 · મંદિર: ₹1,100–5,100'], 'graha_shanti' => ['name' => '{planet} ગ્રહ શાંતિ', 'purpose' => '{planet} ને સંતુલિત કરવો, જેની દશા ચાલે છે પણ જે તમારી કુંડળીમાં નબળો છે.', 'why' => 'તમારી ચાલુ દશાનો સ્વામી {planet} નબળો છે, તેથી આ સમયે સહારો જોઈએ.', 'timing' => '{day} થી શરૂ કરો; પરંપરાગત જાપ સંખ્યા {jaap}.', 'involves' => '{deity} ની પૂજા, {planet} મંત્ર જાપ (જાતે કે પૂજારી પાસે), હવન અને દાન.', 'cost' => 'જાતે જાપ: ₹0 · પૂજારીઓ સાથે: ₹5,100–21,000'], 'deity' => ['Sun' => 'સૂર્ય', 'Moon' => 'શિવ', 'Mars' => 'હનુમાન', 'Mercury' => 'વિષ્ણુ', 'Jupiter' => 'વિષ્ણુ / બૃહસ્પતિ', 'Venus' => 'લક્ષ્મી', 'Saturn' => 'શનિ / હનુમાન', 'Rahu' => 'દુર્ગા', 'Ketu' => 'ગણેશ'], 'note' => 'આ તમારી કુંડળી આધારિત પરંપરાગત સૂચનો છે. ઘરે કરેલી સાચી પ્રાર્થના પણ ચૂકવણીવાળી વિધિ જેટલી જ માન્ય છે, અને કોઈ પૂજા ચોક્કસ પરિણામનું વચન આપી શકતી નથી.'],
